import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D_ZOUi6P.js";const p=JSON.parse('{"title":"Configuration system","description":"","frontmatter":{},"headers":[],"relativePath":"development/configuration-system.md","filePath":"development/configuration-system.md","lastUpdated":1793201370000}'),d={name:"development/configuration-system.md"};function i(s,e,r,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="configuration-system" tabindex="-1">Configuration system <a class="header-anchor" href="#configuration-system" aria-label="Permalink to &quot;Configuration system&quot;">​</a></h1><p>This page explains the architecture of the configuration system and inventory, and the workflows for changing them. Read it before working on <code>lib/agent-data-plane-config*</code>, <code>lib/datadog-agent/config*</code>, <code>schema_overlay.yaml</code>, <code>SalukiConfiguration</code>, <code>DatadogConfiguration</code>, or typed configuration migrations.</p><p>Saluki configures its runtime through a typed boundary. An alternate method of reading configuration, <code>GenericConfiguration</code>, exists in <code>saluki-config</code> for external clients who may want a raw map view, but <code>agent-data-plane</code> doesn&#39;t use it. Don&#39;t delete it as dead code: it&#39;s library code that other projects may depend on.</p><p>Paths and type names can move. If you find this page out of date, update it in the same change.</p><h2 id="why-this-system-exists" tabindex="-1">Why this system exists <a class="header-anchor" href="#why-this-system-exists" aria-label="Permalink to &quot;Why this system exists&quot;">​</a></h2><p><code>GenericConfiguration</code> previously leaked source-language details into components, such as serde names, aliases, parsing, and defaults. The typed system places a translation boundary between configuration sources and runtime code:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Datadog schema config ──&gt; DatadogConfiguration ──&gt; witness drive ──┐</span></span>
<span class="line"><span>                                                                    │</span></span>
<span class="line"><span> Saluki-only config ───────────────&gt; SalukiOnly ───────&gt; seed ──────┤</span></span>
<span class="line"><span>                                                                    v</span></span>
<span class="line"><span>                                                SalukiConfiguration</span></span>
<span class="line"><span>                                                { control, shared, domains }</span></span>
<span class="line"><span>                                                                    │</span></span>
<span class="line"><span>                                           typed slices and Live&lt;T&gt; │</span></span>
<span class="line"><span>                                                                    v</span></span>
<span class="line"><span>                                                         runtime components</span></span></code></pre></div><p>A generated witness trait creates a compile-time obligation to translate every supported Datadog key into <code>SalukiConfiguration</code>.</p><h2 id="architecture-map" tabindex="-1">Architecture map <a class="header-anchor" href="#architecture-map" aria-label="Permalink to &quot;Architecture map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Responsibility</th><th>Canonical location</th></tr></thead><tbody><tr><td>Source-agnostic typed model and <code>Live&lt;T&gt;</code></td><td><code>lib/agent-data-plane-config/</code></td></tr><tr><td>Loading, translation, authority, updates, compatibility</td><td><code>lib/agent-data-plane-config-system/</code></td></tr><tr><td>Datadog source model, witness, classifier, environment decoding</td><td><code>lib/datadog-agent/config/</code></td></tr><tr><td>Hand-edited ADP support inventory for Datadog schema keys</td><td><code>lib/datadog-agent/config/schema/schema_overlay.yaml</code></td></tr><tr><td>Vendored Datadog JSON schema, written in YAML</td><td><code>lib/datadog-agent/config/schema/core/</code></td></tr><tr><td>Overlay types, validation, <code>SALUKI_KEYS</code>, smoke-test metadata</td><td><code>lib/datadog-agent/config-overlay-model/</code></td></tr><tr><td>Configuration registry, <code>run_config_smoke_tests</code>, documentation generation</td><td><code>lib/datadog-agent/config-testing/</code></td></tr><tr><td>Raw map and loader: a general-purpose library, unused by ADP</td><td><code>lib/saluki-config/</code></td></tr><tr><td>Hand-written Datadog witness implementation</td><td><code>lib/agent-data-plane-config-system/src/translators/datadog_translator.rs</code></td></tr><tr><td>Saluki-only source model and <code>seed</code></td><td><code>lib/agent-data-plane-config-system/src/saluki_only.rs</code></td></tr><tr><td>Saluki-only defaults</td><td><code>lib/agent-data-plane-config/src/defaults.rs</code></td></tr><tr><td>Runtime loading and authority selection</td><td><code>lib/agent-data-plane-config-system/src/loaded.rs</code></td></tr><tr><td>Translation gate and update loop</td><td><code>lib/agent-data-plane-config-system/src/system.rs</code></td></tr><tr><td>Datadog environment reader and its Figment provider</td><td><code>lib/datadog-agent/config/src/env_reader.rs</code>, <code>env_provider.rs</code></td></tr><tr><td>Saluki-only environment reader (by convention, with no table)</td><td><code>lib/agent-data-plane-config-system/src/saluki_env_overlay.rs</code></td></tr><tr><td>Merged sources with per-value provenance</td><td><code>lib/agent-data-plane-config-system/src/source.rs</code></td></tr></tbody></table><p>Use <code>ConfigValue&lt;T&gt;</code> in <code>SalukiConfiguration</code> when a default must be detectable, as <code>Provenance::Default</code> versus <code>Provenance::Explicit</code>. See <code>dd_url</code> and <code>site</code> for examples.</p><h3 id="dependency-boundaries" tabindex="-1">Dependency boundaries <a class="header-anchor" href="#dependency-boundaries" aria-label="Permalink to &quot;Dependency boundaries&quot;">​</a></h3><p>The intended end state is:</p><ul><li><code>agent-data-plane-config</code> depends on neither the raw map nor the Datadog source model.</li><li><code>agent-data-plane-config-system</code> bridges sources to the model and constructs no components.</li><li><code>saluki-components</code> define their own input arguments and structs.</li><li><code>bin/agent-data-plane</code> hands each component what it requires.</li></ul><h3 id="the-saluki-components-dependency" tabindex="-1">The <code>saluki-components</code> dependency <a class="header-anchor" href="#the-saluki-components-dependency" aria-label="Permalink to &quot;The \`saluki-components\` dependency&quot;">​</a></h3><p>Initially we wanted <code>saluki-components</code> to depend on <code>agent-data-plane-config</code>, but we changed our mind. We can&#39;t end this dependency immediately because of <code>Live&lt;T&gt;</code> and <code>ConfigValue&lt;T&gt;</code>. However, most migrations don&#39;t require these types. Migrations that don&#39;t require them <strong>SHOULD NOT</strong> depend on types in <code>agent-data-plane-config</code>, and should instead rely on the binary to copy data into fields or an arguments struct that the component presents.</p><p>The end state removes <code>agent-data-plane-config</code> from the <code>saluki-components</code> <code>Cargo.toml</code>. Minimize the impact of that change when migrating components. Some migrations predate this design change: they&#39;re temporary exceptions, so don&#39;t follow them.</p><h2 id="datadog-versus-saluki-keys" tabindex="-1">Datadog versus Saluki keys <a class="header-anchor" href="#datadog-versus-saluki-keys" aria-label="Permalink to &quot;Datadog versus Saluki keys&quot;">​</a></h2><p>A key in the Datadog schema is a Datadog key; a key absent from the overlay is Saluki-only. Names are no help: <code>data_plane.foo</code> can belong to either class.</p><h2 id="datadog-inventory-and-generated-code" tabindex="-1">Datadog inventory and generated code <a class="header-anchor" href="#datadog-inventory-and-generated-code" aria-label="Permalink to &quot;Datadog inventory and generated code&quot;">​</a></h2><p>The vendored schema and overlay have different jobs:</p><ul><li><code>schema/core/*.yaml</code> defines Datadog keys. It <strong>MUST</strong> stay a pristine upstream copy, never edited by hand. Raise any proposed or existing hand edits with the change&#39;s author.</li><li><code>schema_overlay.yaml</code> classifies every schema leaf for ADP. ADP defines its shape.</li></ul><p>Code generated in-tree from the schema and overlay carries <code>@generated</code> and <code>DO NOT EDIT</code> warnings. Regenerate it with:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-schema-overlay</span></span></code></pre></div><h3 id="support-classifications" tabindex="-1">Support classifications <a class="header-anchor" href="#support-classifications" aria-label="Permalink to &quot;Support classifications&quot;">​</a></h3><p>Under <code>inventory</code>, support is <code>full</code>, <code>partial</code>, <code>none</code>, or <code>unknown</code>. <code>excluded</code> is a separate section:</p><ul><li><code>full</code>: ADP reads the key and matches the Agent&#39;s behavior.</li><li><code>partial</code>: ADP reads the key, but differs in some cases. Describe those differences.</li><li><code>none</code>: ADP doesn&#39;t support the key. Choose a severity based on the effect on users, and state whether support is planned. Link an issue when work should be tracked.</li><li><code>unknown</code>: compatibility hasn&#39;t been established. Record what still needs investigation.</li><li><code>excluded</code>: ADP silently ignores the key and omits it from compatibility documentation. Use this for features ADP doesn&#39;t currently support, not to hide gaps that need tracking.</li></ul><p>An investigation toward intended support is <code>planned: true</code>. A documentation-only issue doesn&#39;t mean support is planned.</p><p>Date exclusion notes and name the feature: <code>YYYY-MM-DD: ADP does not currently support &lt;feature&gt;.</code> Avoid generic reasons such as &quot;Core Agent-only&quot; or claims that support can never be added.</p><h2 id="environment-variables-and-key-shape" tabindex="-1">Environment variables and key shape <a class="header-anchor" href="#environment-variables-and-key-shape" aria-label="Permalink to &quot;Environment variables and key shape&quot;">​</a></h2><p>The Datadog Agent doesn&#39;t derive a variable&#39;s name from its key path: <code>DD_PROXY_HTTP</code> reaches <code>proxy.http</code>, while <code>DD_DOGSTATSD_PORT</code> reaches the flat <code>dogstatsd_port</code>. No separator convention reproduces this. Datadog keys read the environment through the generated tables, and Saluki-only keys are derived through a serde workaround. The environment is read by <code>apply_datadog_env</code> and by the Saluki-only reader.</p><p><strong>A modeled key arrives in the Agent&#39;s canonical shape.</strong> A source model <strong>MUST</strong> read that shape: don&#39;t add a <code>#[serde(rename)]</code> or <code>#[serde(alias)]</code>. Unmodeled environment variables aren&#39;t read.</p><h2 id="scalar-leaf-coercion" tabindex="-1">Scalar leaf coercion <a class="header-anchor" href="#scalar-leaf-coercion" aria-label="Permalink to &quot;Scalar leaf coercion&quot;">​</a></h2><p><code>DatadogConfiguration</code> scalar leaves accept what the Agent&#39;s permissive casting accepts. Code generation attaches a <code>cast_de.rs</code> coercion to each schema type. For example, <code>dogstatsd_port: &quot;8125.0&quot;</code> is valid and coerced to the integer <code>8125</code>, and <code>1</code> or <code>&quot;T&quot;</code> is coerced to a <code>bool</code>.</p><h2 id="documented-enum-settings" tabindex="-1">Documented enum settings <a class="header-anchor" href="#documented-enum-settings" aria-label="Permalink to &quot;Documented enum settings&quot;">​</a></h2><p>A <code>string</code> setting whose schema documentation names a closed set of values becomes an enum in <code>agent-data-plane-config</code> with <code>#[default]</code> and <code>FromStr</code>. Match the Agent&#39;s behavior: warn and fall back, or record a <code>TranslateError</code>. Serialize using the <code>FromStr</code> spelling.</p><h2 id="saluki-only-values" tabindex="-1">Saluki-only values <a class="header-anchor" href="#saluki-only-values" aria-label="Permalink to &quot;Saluki-only values&quot;">​</a></h2><p>Values absent from the Datadog schema reach <code>SalukiConfiguration</code> through the <code>SalukiOnly</code> source model. Its field hierarchy matches the source path exactly: don&#39;t add serde aliases.</p><p>A <code>SalukiOnly</code> field and a <code>DatadogConfiguration</code> field that map to the same destination is a bug. Keep the authoritative Datadog path and delete the duplicate Saluki-only path.</p><h2 id="defaults" tabindex="-1">Defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to &quot;Defaults&quot;">​</a></h2><p>Defaults belong in the configuration layer, and exactly one layer owns each default:</p><table tabindex="0"><thead><tr><th>Source class</th><th>Model type</th><th>Default owner</th><th>Translation behavior</th></tr></thead><tbody><tr><td>Saluki-only</td><td><code>Option&lt;T&gt;</code></td><td>No default</td><td><code>seed</code> preserves <code>None</code></td></tr><tr><td>Saluki-only</td><td><code>T</code></td><td><code>agent-data-plane-config/src/defaults.rs</code></td><td><code>seed</code> assigns the resolved value</td></tr><tr><td>Witnessed</td><td><code>T</code></td><td>Generated Datadog schema default</td><td><code>drive</code> always writes it</td></tr><tr><td>Witnessed</td><td><code>Option&lt;T&gt;</code></td><td>No default</td><td><code>drive</code> preserves <code>None</code></td></tr></tbody></table><p>Define each Saluki-only default once in <code>lib/agent-data-plane-config/src/defaults.rs</code>. Source and model defaults must reference that definition, rather than restating its value. If the component requires a value, model it as <code>T</code>: use <code>Option&lt;T&gt;</code> only when absence is meaningful, not to defer a default.</p><p>Push source parsing, defaults, and input validation to the configuration boundary. Components keep only validation that is business logic.</p><h2 id="merged-sources-and-the-raw-view" tabindex="-1">Merged sources and the raw view <a class="header-anchor" href="#merged-sources-and-the-raw-view" aria-label="Permalink to &quot;Merged sources and the raw view&quot;">​</a></h2><p><code>SourceTree</code> is the merged configuration: every value an input supplied, each with the provenance of the input that supplied it. <code>ConfigurationSystem</code> retains the tree it translated from, which is what the startup compatibility gate, the privileged <code>/config</code> route, and the <code>runtime_config_dump.yaml</code> flare artifact read. Those readers need the keys that the typed model doesn&#39;t carry, so they read the sources rather than the model.</p><h3 id="runtime-updates" tabindex="-1">Runtime updates <a class="header-anchor" href="#runtime-updates" aria-label="Permalink to &quot;Runtime updates&quot;">​</a></h3><p>Startup translation is strict. Live updates are translated against tentative state: success atomically replaces both the typed model and the retained sources, while failure keeps the last-known-good model and leaves the sources as they were.</p><h2 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h2><h3 id="add-or-change-a-witnessed-key" tabindex="-1">Add or change a witnessed key <a class="header-anchor" href="#add-or-change-a-witnessed-key" aria-label="Permalink to &quot;Add or change a witnessed key&quot;">​</a></h3><ol><li>Confirm its <code>schema_overlay.yaml</code> classification. If support becomes <code>full</code> or <code>partial</code>, provide the required metadata, and expect a new witness method after generation.</li><li>Add or refine its destination in <code>control</code>, <code>shared</code>, or <code>domains</code>, based on who consumes it.</li><li>Run <code>make build-schema-overlay</code>.</li><li>Implement the generated <code>consume_&lt;key&gt;</code> in <code>DatadogTranslator</code>, and find the right home for it in <code>SalukiConfiguration</code>.</li></ol><p>An inventory key marked <code>none</code> or <code>unknown</code>, or a key under <code>excluded</code>, is absent from the witnessed model.</p><h3 id="add-or-change-a-saluki-only-key" tabindex="-1">Add or change a Saluki-only key <a class="header-anchor" href="#add-or-change-a-saluki-only-key" aria-label="Permalink to &quot;Add or change a Saluki-only key&quot;">​</a></h3><ol><li>Verify that the key is absent from <code>schema_overlay.yaml</code>.</li><li>Add its destination to the correct <code>SalukiConfiguration</code> slice.</li><li>If it has a default, define it once in <code>agent-data-plane-config/src/defaults.rs</code>, and reference it from the model and source defaults.</li><li>Add the exact source hierarchy and a reliable parsing type to <code>SalukiOnly</code>. A <strong>nested</strong> key requires this: the Saluki-only environment reader discovers paths from <code>SalukiOnly</code>, so without a field, the key is unreachable from the environment.</li><li>Add one <code>seed</code> assignment to the destination.</li><li>Keep the legacy <code>SALUKI_KEYS</code> consistent with the source key, type, and default.</li></ol><h3 id="migrate-a-raw-consumer" tabindex="-1">Migrate a raw consumer <a class="header-anchor" href="#migrate-a-raw-consumer" aria-label="Permalink to &quot;Migrate a raw consumer&quot;">​</a></h3><ol><li>List every key the consumer reads, including serde fields, flattened structs, aliases, direct accessors, watches, and stored raw maps.</li><li>Record current parsing, validation, fallback, normalization, default, and update behavior before deleting source code.</li><li>Classify each key by schema membership, and check for a duplicate between witnessed and Saluki-only paths.</li><li>Search all consumers. Put a value in <code>domains</code> when one domain owns it, and in <code>shared</code> when multiple domains consume it. Components don&#39;t read <code>control</code>.</li><li>Add any missing model, witness, or seed path with the workflows above.</li><li>Delete <code>from_configuration</code>, and pick its replacement by the shape of the <code>*Configuration</code> struct: <ul><li>Fewer than four fields: <code>new(...)</code> taking concrete values.</li><li>Four or more fields: make them <code>pub</code> and let the caller build the struct by field, with no constructor. Avoid introducing a new arguments or settings struct, and don&#39;t implement <code>Default</code> or <code>Deserialize</code> on the configuration struct.</li><li>Runtime wiring the caller can&#39;t read out of configuration: have the caller create it and assign what the component needs to a <code>pub</code> field. See <code>aggregate_context_snapshot_channel</code> and <code>AggregateConfiguration::context_snapshot_receiver</code>.</li><li>Values that change at runtime: pass a narrow <code>Live&lt;T&gt;</code>, and rebuild the reactive state after <code>changed()</code>.</li></ul></li><li>Remove source serde, Datadog key names, raw-map access, key watches, parsing, configuration defaults, and code made unused by the cutover. <code>#[allow(dead_code)]</code> isn&#39;t an acceptable way to keep migration residue.</li><li>Update topology call sites and tests. Preserve behavior tests by using typed inputs, and remove tests only when they tested legacy deserialization and nothing else.</li><li>Remove the component&#39;s <code>run_config_smoke_tests</code> invocation once it no longer deserializes from <code>GenericConfiguration</code>. Replace migrated structs in <code>used_by</code> with <code>TypedConfigSystem</code> in <code>schema_overlay.yaml</code>, or with the string <code>TYPED_CONFIG_SYSTEM</code> in <code>SALUKI_KEYS</code>.</li><li>Test higher-risk cutovers with correctness or integration tests that exercise the affected configurations.</li></ol><p>A cutover should be behaviorally transparent. If the old behavior conflicts with the source schema or the typed system&#39;s invariants, surface the conflict rather than silently choosing one. Don&#39;t leave deserialization artifacts behind after a cutover: for example, drop <code>derive(Deserialize)</code>, and collapse a held <code>Option&lt;SomeType&gt;</code> to a held <code>SomeType</code> where possible.</p><h3 id="update-the-vendored-schema" tabindex="-1">Update the vendored schema <a class="header-anchor" href="#update-the-vendored-schema" aria-label="Permalink to &quot;Update the vendored schema&quot;">​</a></h3><p>Use the <code>config-schema-update</code> skill, which walks through comparing, vendoring, and classifying a new upstream schema.</p><h2 id="review-checklist" tabindex="-1">Review checklist <a class="header-anchor" href="#review-checklist" aria-label="Permalink to &quot;Review checklist&quot;">​</a></h2><p>For any configuration change, check the risks:</p><ul><li><strong>Reachability</strong>: every formerly configurable value still has a path from source to model to consumer.</li><li><strong>Defaults</strong>: the effective default is unchanged, and is stated once in the configuration layer.</li><li><strong>Input handling</strong>: parsing, coercion, normalization, and validation moved to the configuration layer.</li><li><strong>Model boundary</strong>: components receive only the domain and shared slices they need.</li><li><strong>Dynamic behavior</strong>: startup and update paths construct the same reactive state from typed input.</li><li><strong>Test preservation</strong>: deleting legacy deserialization coverage didn&#39;t delete behavioral coverage.</li></ul><h2 id="check-your-work" tabindex="-1">Check your work <a class="header-anchor" href="#check-your-work" aria-label="Permalink to &quot;Check your work&quot;">​</a></h2><p>The <code>Makefile</code> is authoritative:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-schema-overlay</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # regenerate code</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fmt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # use this, not cargo fmt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tests</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # quick compilation check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # required to pass CI</span></span></code></pre></div>`,65)])])}const g=a(d,[["render",i]]);export{p as __pageData,g as default};
